    private void BTNSalvarActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_BTNSalvarActionPerformed
        
        String nome = TXTFNome.getText().trim();
        String email = TXTFEmail.getText().trim();
        String cidade = TXTFCidade.getText().trim();
        String estado = CBOXEstado.getSelectedItem().toString();
        
        if (nome.isEmpty() || email.isEmpty() || cidade.isEmpty() || estado.isEmpty()) {
            
            JOptionPane.showMessageDialog(this, "Preencha todos os campos !", "Aviso", JOptionPane.WARNING_MESSAGE);
            return;
        }
        
        else {
            
            try {
                    
                File arquivo = new File("clientes.csv");
                
                boolean novoArquivo = !arquivo.exists();
                    
                    try(BufferedWriter escrita = new BufferedWriter(new FileWriter(arquivo, true))) {
                        
                        if (novoArquivo) {
                            
                        escrita.write("Nome;Email;Cidade;Estado");
                        escrita.newLine();
                        
                        }
                        
                    escrita.write(nome + ";" + email + ";" + cidade + ";" + estado + System.lineSeparator());
                    JOptionPane.showMessageDialog(this, "Cliente salvo", "Cliente", JOptionPane.INFORMATION_MESSAGE);
                    limparTXTF();
                    }
                 
                
                
            } catch (IOException e ) {
                
            JOptionPane.showMessageDialog(this, "ERRO AO CRIAR O ARQUIVO", "erro", JOptionPane.ERROR_MESSAGE);
            return;
            }                    
        }

        
    }//GEN-LAST:event_BTNSalvarActionPerformed

